window.EDAG_QUESTIONS = [{"id":"practice-1-1","chapter":1,"topic":"Pure EC vs pure-play","section":"s2","prompt":"Penjual hanya memiliki situs dan gudang. Pesanan serta pembayaran sepatu dilakukan online, lalu sepatu dikirim kurir. Pasangan klasifikasi paling tepat pada dimensi organisasi dan transaksi adalah…","reason":"Kanal organisasi dan digitasi transaksi adalah dua sumbu berbeda. Tidak adanya toko retail mendukung pure-play pada definisi materi, sedangkan produk yang dikirim fisik membuat transaksi partial EC. Gudang tidak menggugurkan pure-play.","options":["Click-and-mortar; transaksi pure EC","Pure-play; transaksi pure EC","Brick-and-mortar; transaksi partial EC","Pure-play; transaksi partial EC"],"analysis":["Gudang bukan toko retail; pemenuhan fisik juga menggugurkan pure EC.","Menyamakan kanal online dengan digitasi seluruh proses mengabaikan pengiriman.","Aset gudang tidak berarti kanal penjualan berupa toko fisik.","Kanal penjualan online dan pengiriman fisik dapat hadir bersamaan."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-2","chapter":1,"topic":"Relasi transaksi","section":"s3","prompt":"Sebuah marketplace mempertemukan dua mahasiswa yang menjual-beli kalkulator pribadi. Pada hari yang sama, marketplace menjual paket iklan kepada toko alat tulis. Klasifikasi dua transaksi tersebut berturut-turut adalah…","reason":"Pilih unit analisis transaksinya. Penjual dan pembeli kalkulator adalah individu; penjualan layanan iklan berlangsung antara platform bisnis dan toko bisnis. Kehadiran marketplace tidak mengubah identitas pihak pada transaksi kalkulator.","options":["C2C kemudian B2B","B2C kemudian C2B","B2B2C kemudian B2C","C2C kemudian C2B"],"analysis":["Relasi barang antarmahasiswa berbeda dari layanan iklan antarbisnis.","Platform tidak menjadi penjual kalkulator; toko juga bukan konsumen individu.","Tidak ada bukti rantai dua bisnis yang menjual kalkulator dalam kasus.","Pengiklan adalah bisnis, sehingga layanan platform bukan transaksi konsumen-ke-bisnis."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-3","chapter":1,"topic":"Framework EC","section":"s4","prompt":"Tim sudah mempercepat halaman checkout. Namun 12% pesanan yang dibayar dibatalkan karena stok pemasok tidak sinkron. Investasi berikut yang paling langsung menangani mekanisme kegagalan adalah…","reason":"Kegagalan berada pada hubungan order, stok dan pemenuhan. Perbaikan perlu menghubungkan data/proses antarpihak. Promosi atau personalisasi dapat memperbesar permintaan tanpa menambah kemampuan memenuhi pesanan.","options":["Validasi alamat dan penjadwalan kapasitas kurir","Pemeriksaan kredit dan konfirmasi ulang pembeli","Sinkronisasi stok dan reservasi lintas mitra","Rekonsiliasi pembayaran dan percepatan refund"],"analysis":["Menangani kelayakan pengiriman setelah barang tersedia; bukti kasus menunjuk stok pemasok.","Menangani risiko pembayaran atau niat pembeli, sedangkan order telah dibayar dan stok tidak sinkron.","Menyatukan ketersediaan dengan komitmen order menangani penyebab pembatalan.","Mengurangi dampak finansial pembatalan, tetapi barang yang dijanjikan tetap tidak tersedia."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-4","chapter":1,"topic":"Business model canvas","section":"s8","prompt":"Platform buku kampus mengklaim nilai “edisi tepat, ambil hari ini”. Dari empat perubahan berikut, mana yang paling menguji konsistensi antarblok canvas?","reason":"Proposisi nilai tentang edisi dan waktu harus didukung sumber daya data serta aktivitas pemenuhan. Menambah pendapatan atau tampilan tidak membuktikan kemampuan menyampaikan janji. Canvas merupakan hubungan keputusan, bukan daftar fitur.","options":["Validasi klik kanal dan respons kampanye rujukan","Validasi ISBN dan kapasitas titik pengambilan","Validasi minat segmen dan pertumbuhan langganan","Validasi biaya pemasok dan margin setiap kategori"],"analysis":["Menguji akuisisi pelanggan; keberhasilan janji fulfillment memerlukan bukti operasi.","Menguji ketepatan edisi serta kemampuan memenuhi janji waktu melalui aktivitas dan sumber daya.","Menguji permintaan dan penerimaan berulang, belum kemampuan menyediakan edisi tepat hari ini.","Menguji kelayakan biaya, tetapi margin tidak membuktikan ketepatan edisi atau kesiapan pengambilan."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-5","chapter":1,"topic":"Revenue vs value proposition","section":"s9","prompt":"Pelanggan membayar Rp40.000 per bulan untuk akses perbandingan pemasok. Platform juga menerima komisi untuk transaksi yang terjadi melalui rujukannya. Pasangan pernyataan paling tepat adalah…","reason":"Subscription dan referral commission menjelaskan arus pendapatan. Alasan pelanggan mau membayar adalah nilai pencarian/perbandingan yang diperoleh. Model yang sama dapat memiliki beberapa revenue streams sekaligus.","options":["Perbandingan dan subscription adalah customer segments","Affiliate fee dan perbandingan adalah key resources","Subscription dan komisi adalah value propositions","Subscription dan affiliate fee adalah revenue streams"],"analysis":["Keduanya bukan kelompok pelanggan yang dilayani.","Komisi adalah penerimaan; kemampuan perbandingan perlu sumber daya pendukung.","Cara menarik uang berbeda dari manfaat bagi pelanggan.","Keduanya menyebut cara platform menerima imbalan."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-6","chapter":1,"topic":"Reach, richness, affiliation","section":"s5","prompt":"Marketplace sudah memuat satu juta SKU, tetapi deskripsi kompatibilitas sangat minim. Menambah video instalasi dan filter kecocokan terutama memperbaiki…","reason":"Kasus sudah memiliki jangkauan penawaran yang luas. Kekurangannya adalah kedalaman informasi dan dukungan keputusan. Video dan filter terutama meningkatkan richness; efek lain mungkin ada, tetapi bukan pembeda utama.","options":["Richness dalam informasi produk","Reach dalam cakupan penjual","Affiliation dalam struktur kemitraan","Digitization dalam bentuk barang"],"analysis":["Kedalaman dan relevansi informasi membantu menilai kecocokan.","Tidak ada penambahan pihak atau perluasan pasar yang dinyatakan.","Kasus tidak mengubah hubungan atau kerja sama mitra.","Video tidak mengubah produk fisik menjadi barang digital."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-7","chapter":1,"topic":"GMV dan unit economics","section":"s9","prompt":"Marketplace memfasilitasi 100 order, masing-masing Rp200.000. Komisi 5%; biaya variabel platform Rp7.000 per order. Mengabaikan biaya tetap, kontribusi total platform adalah…","reason":"GMV Rp20 juta bukan pendapatan yang seluruhnya menjadi hak platform. Komisi = 5% × Rp20 juta = Rp1 juta. Biaya variabel = 100 × Rp7.000 = Rp700.000; kontribusi Rp300.000 sebelum biaya tetap.","options":["Rp700.000 sebelum biaya tetap","Rp300.000 sebelum biaya tetap","Rp1.000.000 sebelum biaya tetap","Rp19.300.000 sebelum biaya tetap"],"analysis":["Ini total biaya variabel, bukan kontribusi pendapatan.","Pendapatan komisi dikurangi biaya variabel menghasilkan kontribusi ini.","Ini pendapatan komisi sebelum dikurangi biaya variabel.","Ini keliru memperlakukan seluruh GMV sebagai pendapatan platform."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-8","chapter":1,"topic":"EC dan EB","section":"s1","prompt":"Dengan definisi EC sempit dan EB luas yang dinyatakan materi, portal pelatihan internal dapat termasuk EB meskipun tidak memproses penjualan kepada pelanggan.","reason":"EB mencakup proses internal dan pembelajaran, sedangkan EC sempit menitikberatkan pertukaran komersial. Pernyataan menetapkan definisi dengan jelas sehingga tidak bergantung pada penggunaan EC luas di bagian lain.","options":["Benar","Salah"],"analysis":["EB mencakup proses internal dan pembelajaran, sedangkan EC sempit menitikberatkan pertukaran komersial. Pernyataan menetapkan definisi dengan jelas sehingga tidak bergantung pada penggunaan EC luas di bagian lain.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-9","chapter":1,"topic":"Manfaat dan hasil","section":"s5","prompt":"Jika biaya akuisisi per pelanggan naik lebih cepat daripada kontribusi pembeliannya, pertumbuhan order saja belum cukup membuktikan model EC makin menguntungkan.","reason":"Pertumbuhan volume harus dibandingkan dengan biaya dan margin. Order merupakan aktivitas transaksi; laba memerlukan pendapatan yang menutup biaya terkait. Pernyataan tidak menyatakan pertumbuhan selalu buruk, hanya membatasi inferensi.","options":["Benar","Salah"],"analysis":["Pertumbuhan volume harus dibandingkan dengan biaya dan margin. Order merupakan aktivitas transaksi; laba memerlukan pendapatan yang menutup biaya terkait. Pernyataan tidak menyatakan pertumbuhan selalu buruk, hanya membatasi inferensi.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-10","chapter":1,"topic":"Jaringan dan aktor","section":"s3","prompt":"Karena perusahaan mengakses katalog pemasok melalui internet publik, transaksi pembelian komponen itu diklasifikasikan B2C, bukan B2B.","reason":"Internet adalah kanal jaringan. Identitas serta tujuan transaksi tetap antarorganisasi, sehingga B2B. Penggunaan jaringan publik tidak mengubah pembeli bisnis menjadi konsumen pribadi.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Internet adalah kanal jaringan. Identitas serta tujuan transaksi tetap antarorganisasi, sehingga B2B. Penggunaan jaringan publik tidak mengubah pembeli bisnis menjadi konsumen pribadi."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-2-1","chapter":2,"topic":"Peran perantara","section":"s5","prompt":"Produsen menjual langsung melalui platform, melewati distributor lama. Platform kemudian mengurus pembayaran, reputasi dan pengiriman. Kesimpulan paling lengkap adalah…","reason":"Distributor tertentu dihapus, tetapi fungsi matching, trust dan distribusi tetap diperlukan serta dilaksanakan perantara baru. Satu rantai dapat memperlihatkan disintermediation dan reintermediation sekaligus pada peran berbeda.","options":["Distributor diganti; disintermediation tidak terjadi dalam rantai","Distributor tetap ada; platform hanya menjadi kanal komunikasinya","Distributor dilewati; fungsi perantara dibentuk ulang","Distributor dilewati; distribusi berubah menjadi fungsi pembeli"],"analysis":["Peniadaan distributor tetap dapat disebut disintermediation pada mata rantai tersebut meski muncul perantara baru.","Kasus menyatakan distributor lama dilewati dan platform melaksanakan fungsi transaksi.","Disintermediation terjadi pada distributor dan reintermediation pada layanan platform.","Pembeli tidak dinyatakan mengambil alih pembayaran, reputasi, dan pengiriman yang dikelola platform."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-2","chapter":2,"topic":"Struktur pasar","section":"s4","prompt":"Satu perusahaan membuka portal bagi 40 pemasok untuk mengajukan penawaran atas spesifikasi pembeliannya. Portal dimiliki dan diatur perusahaan tersebut. Klasifikasi terbaik adalah…","reason":"Pengendali merupakan satu organisasi pembeli dan calon penjualnya banyak. Itu private buy-side dalam taksonomi materi. Banyak pemasok tidak cukup untuk menyebut public many-to-many.","options":["Public marketplace dengan struktur many-to-many","Private marketplace dengan struktur buy-side","Public marketplace dengan struktur sell-side","Private marketplace dengan struktur sell-side"],"analysis":["Kasus hanya menyebut satu pembeli dan pengendali yang sama.","Satu pembeli mengatur pasar yang melibatkan banyak pemasok.","Tidak ada pemilik pihak ketiga atau satu penjual utama.","Sell-side berpusat pada satu penjual melayani banyak pembeli."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-3","chapter":2,"topic":"Dutch vs reverse auction","section":"s8","prompt":"Seorang penjual menawarkan satu mesin, memulai harga tinggi lalu menurunkannya sampai salah satu pembeli menerima. Pilihan mana paling tepat?","reason":"Arah harga menurun tidak menentukan reverse auction. Satu penjual menawarkan barang kepada banyak calon pembeli, dengan mekanisme Dutch auction. Reverse auction menempatkan banyak pemasok bersaing bagi satu pembeli.","options":["Double auction pada struktur banyak pihak","English auction dengan penawaran tertutup","Dutch auction pada struktur satu penjual","Reverse auction pada struktur satu pembeli"],"analysis":["Tidak ada banyak penawaran jual yang dicocokkan dengan penawaran beli.","English biasanya bid pembeli meningkat; mekanismenya berbeda dari kasus.","Harga turun sampai diterima, dengan satu penjual sebagai pusat.","Tidak ada satu pembeli yang mengundang persaingan banyak pemasok."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-4","chapter":2,"topic":"Storefront, mall, portal","section":"s6","prompt":"Situs X berisi direktori 200 toko dan mengirim pengunjung ke situs masing-masing untuk transaksi. Situs Y menjual katalog satu perusahaan. Pasangan paling tepat adalah…","reason":"X menggabungkan beberapa toko dengan pola referring mall. Y merupakan storefront satu penjual. Tidak adanya shared checkout tidak mencegah X diklasifikasikan mall dalam bentuk direktori.","options":["X storefront; Y corporate portal","X buy-side exchange; Y shared mall","X storefront; Y public exchange","X referring mall; Y storefront"],"analysis":["X bukan toko tunggal dan Y dinyatakan menjual produk.","Tidak ada organisasi pembeli pusat atau kumpulan toko di Y.","Kedua label mengabaikan struktur penjual yang disebutkan.","Jumlah toko dan lokasi penyelesaian transaksi membedakan keduanya."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-5","chapter":2,"topic":"Front end dan back end","section":"s3","prompt":"Pembeli melihat “pembayaran selesai” tetapi order tidak muncul di gudang. Log gateway menunjukkan pembayaran disetujui. Lokasi investigasi pertama yang paling relevan adalah…","reason":"Bukti menunjukkan antarmuka dan otorisasi merespons, tetapi handoff ke fulfillment gagal. Perlu memeriksa pencatatan status order dan integrasi gudang. Tidak cukup menilai tampilan berhasil sebagai bukti seluruh proses selesai.","options":["Reservasi kapasitas kurir dan pencetakan label","Indeks katalog dan validasi isi keranjang","Transisi status order dan integrasi fulfillment","Validasi kartu dan permintaan otorisasi ulang"],"analysis":["Ini tahap setelah gudang menerima order; kasus belum menunjukkan order mencapai tahap tersebut.","Pemilihan produk mendahului pembayaran; titik pertama yang terindikasi gagal adalah pemindahan order ke fulfillment.","Menelusuri sambungan setelah persetujuan pembayaran hingga order masuk antrean gudang.","Gateway sudah memberikan persetujuan; mengulang otorisasi belum menjelaskan hilangnya order dan berisiko duplikasi."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-6","chapter":2,"topic":"Crowdsourcing","section":"s11","prompt":"Kontes inovasi menerima 5.000 ide. Tim ingin memilih solusi teknis untuk batas biaya dan performa tertentu. Tahap berikut yang paling dapat dipertanggungjawabkan adalah…","reason":"Jumlah kontribusi menunjukkan partisipasi, belum membuktikan kelayakan. Solusi perlu dievaluasi dengan kriteria biaya/performa, dapat dimodifikasi, lalu diprioritaskan. Voting dapat menjadi input, bukan pengganti verifikasi teknis.","options":["Urutkan biaya usulan, lalu pilih estimasi terendah","Saring kelayakan, uji kriteria, lalu prioritaskan","Urutkan jumlah suara, lalu biayai prototipe teratas","Urutkan kebaruan, lalu pilih ide paling berbeda"],"analysis":["Estimasi biaya perlu diverifikasi dan dibandingkan dengan kebutuhan performa, bukan digunakan sendirian.","Menghubungkan seleksi dengan batas biaya dan performa yang telah ditetapkan.","Popularitas dapat menyaring perhatian tetapi tidak menggantikan kelayakan terhadap dua batas kasus.","Kebaruan penting untuk inovasi, tetapi ide baru bisa melanggar batas performa atau biaya."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-7","chapter":2,"topic":"AR vs visual search","section":"s10","prompt":"Aplikasi A mencari kursi serupa dari foto pengguna. Aplikasi B menampilkan model kursi digital di atas gambar ruang tamu secara langsung. Perbedaan yang paling tepat adalah…","reason":"A menggunakan gambar sebagai kueri pencarian. B menambahkan objek digital pada pandangan ruang nyata, sehingga AR. Kedua aplikasi dapat membantu keputusan, tetapi mekanisme representasinya berbeda.","options":["A virtual reality; B visual search","A social search; B crowdsourcing","A visual search; B augmented reality","A augmented reality; B virtual reality"],"analysis":["A tidak membuat lingkungan virtual; B menempatkan objek secara visual.","Kasus tidak menyebut relasi sosial atau kontribusi crowd.","Kueri visual berbeda dari overlay objek pada lingkungan nyata.","A tidak menambah objek ke lingkungan; B tidak menggantinya sepenuhnya."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-8","chapter":2,"topic":"Shopping cart","section":"s7","prompt":"Keranjang menahan pilihan pengguna selama sesi. Dalam pemetaan fungsi EC, penyimpanan pilihan ini merupakan bukti reservasi persediaan gudang.","reason":"Keranjang menyimpan item yang dipilih. Reservasi adalah komitmen stok oleh proses inventori; keduanya dapat dihubungkan, tetapi kasus hanya menyebut penyimpanan pilihan sehingga bukti reservasi belum ada.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Keranjang menyimpan item yang dipilih. Reservasi adalah komitmen stok oleh proses inventori; keduanya dapat dihubungkan, tetapi kasus hanya menyebut penyimpanan pilihan sehingga bukti reservasi belum ada.","Keranjang menyimpan item yang dipilih. Reservasi adalah komitmen stok oleh proses inventori; keduanya dapat dihubungkan, tetapi kasus hanya menyebut penyimpanan pilihan sehingga bukti reservasi belum ada."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-9","chapter":2,"topic":"Komunitas dan marketplace","section":"s9","prompt":"Komunitas profesional dengan keanggotaan terbatas dapat menggunakan wiki dan forum meskipun tidak memiliki mekanisme jual beli.","reason":"Komunitas dibedakan oleh kepentingan dan interaksi anggotanya. Marketplace berfungsi memfasilitasi pertukaran pasar. Tools kolaborasi tidak mewajibkan adanya transaksi komersial.","options":["Benar","Salah"],"analysis":["Komunitas dibedakan oleh kepentingan dan interaksi anggotanya. Marketplace berfungsi memfasilitasi pertukaran pasar. Tools kolaborasi tidak mewajibkan adanya transaksi komersial.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-10","chapter":2,"topic":"Metaverse dan interoperabilitas","section":"s10","prompt":"Mal virtual X mengekspor avatar dalam format yang dapat diimpor platform Y. Bukti itu menunjukkan interoperabilitas representasi avatar, tetapi belum membuktikan hak pakai barang virtual ikut berlaku di Y.","reason":"Portabilitas representasi dan pengakuan hak aset merupakan lapisan berbeda. Impor bentuk avatar menguji pertukaran data, sedangkan lisensi, identitas dan pengakuan transaksi membutuhkan aturan serta dukungan platform penerima.","options":["Benar","Salah"],"analysis":["Portabilitas representasi dan pengakuan hak aset merupakan lapisan berbeda. Impor bentuk avatar menguji pertukaran data, sedangkan lisensi, identitas dan pengakuan transaksi membutuhkan aturan serta dukungan platform penerima.","Menolak klaim ini tidak sesuai mekanisme kasus. Portabilitas representasi dan pengakuan hak aset merupakan lapisan berbeda. Impor bentuk avatar menguji pertukaran data, sedangkan lisensi, identitas dan pengakuan transaksi membutuhkan aturan serta dukungan platform penerima."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-3-1","chapter":3,"topic":"Omnichannel","section":"s3","prompt":"Retailer memiliki web dan toko, tetapi stok serta retur tidak terhubung. Pembeli online ditolak saat meminta retur di toko. Perbaikan yang paling langsung menuju omnichannel adalah…","reason":"Omnichannel menekankan kesinambungan pengalaman dan integrasi proses. Dua kanal yang berdiri sendiri baru menunjukkan multichannel. Menambah kanal lain tanpa menyatukan order, stok dan kebijakan hanya memperluas fragmentasi.","options":["Satukan identitas order, stok, dan prosedur retur","Satukan merek, promosi, dan kalender peluncuran","Satukan target omzet dan pelaporan kedua kanal","Satukan katalog, foto, dan deskripsi setiap produk"],"analysis":["Menghubungkan bukti transaksi dan pelaksanaan layanan lintas kanal.","Konsistensi komunikasi belum memungkinkan toko memproses retur order web.","Pelaporan bersama dapat mendukung koordinasi, tetapi transaksi dan kebijakan retur belum terintegrasi.","Konsistensi informasi produk tidak memberi kemampuan menerima atau membukukan retur lintas kanal."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-2","chapter":3,"topic":"Kesesuaian produk","section":"s1","prompt":"Dua produk memberi margin identik: e-book standar dan makanan segar dengan jendela kirim dua jam. Perbedaan desain operasi paling penting adalah…","reason":"Makanan segar membawa variasi kualitas, umur simpan dan kendala waktu fisik. Katalog sama baiknya tidak meniadakan kebutuhan kapasitas serta kondisi kirim. E-book memerlukan hak akses dan delivery digital, dengan kendala berbeda.","options":["Makanan memerlukan kendali lisensi dan hak unduh","Keduanya cukup memakai antrean fulfillment identik","Keduanya cukup memakai kapasitas server identik","Makanan memerlukan kendali kondisi dan slot kirim"],"analysis":["Kontrol ini lebih langsung terkait distribusi konten digital daripada kualitas makanan selama pengiriman.","Antrean generik mengabaikan kedaluwarsa, wilayah, dan kapasitas pengiriman makanan.","Kapasitas digital relevan untuk pemesanan, tetapi tidak menangani bottleneck pemenuhan fisik.","Umur simpan serta jendela dua jam menuntut kapasitas dan kondisi pengiriman fisik."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-3","chapter":3,"topic":"Integrasi e-tailing","section":"s2","prompt":"Katalog menunjukkan lima unit stok; tiga order hampir bersamaan diterima masing-masing dua unit. Pembayaran berhasil, tetapi gudang hanya memiliki lima. Kontrol yang paling langsung relevan adalah…","reason":"Masalahnya overselling karena total komitmen melebihi ketersediaan. Reservasi dan pemeriksaan konsisten pada proses order menangani sumber kegagalan. Menambah layanan purnajual membantu dampak, tetapi tidak mencegah kejadian.","options":["Pemeriksaan stok setiap awal sesi belanja pelanggan","Rekonsiliasi stok ketika picking gudang dimulai","Reservasi stok konsisten saat order dikonfirmasi","Sinkronisasi katalog setiap akhir batch pembayaran"],"analysis":["Pemeriksaan awal menjadi usang ketika pembeli lain membuat komitmen sebelum checkout.","Menemukan kekurangan sesudah janji dan pembayaran; berguna untuk audit tetapi terlambat mencegah overselling.","Komitmen order harus mengurangi ketersediaan secara konsisten meski permintaan hampir bersamaan.","Jeda batch masih memungkinkan beberapa order membaca stok yang sama sebelum pembaruan."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-4","chapter":3,"topic":"Channel conflict","section":"s11","prompt":"Produsen memberi diskon web besar, sementara dealer tetap membiayai demo dan layanan. Banyak pelanggan mencoba di dealer lalu membeli web. Pilihan paling menyasar akar konflik adalah…","reason":"Dealer menanggung aktivitas yang menciptakan nilai, tetapi transaksi berpindah sehingga kompensasinya hilang. Penyelarasan peran dan insentif menangani konflik ini. Menyamakan harga saja belum membagi biaya atau nilai pelayanan.","options":["Tambah target demo dan bonus berdasarkan kunjungan","Atur atribusi layanan dan pembagian imbalan kanal","Samakan harga katalog dan ukur omzet tiap kanal","Pisahkan segmen kanal berdasarkan usia pelanggan"],"analysis":["Menghargai aktivitas, tetapi tanpa hubungan kualitas atau konversi dapat mendorong demo yang tidak menghasilkan nilai.","Mengembalikan imbalan kepada kanal yang berkontribusi pada keputusan pembelian.","Harga seragam mengurangi satu pemicu, tetapi dealer masih dapat memberi demo tanpa memperoleh bagian transaksi.","Segmentasi usia tidak langsung mengatasi pelanggan yang memakai demo dealer lalu membeli di web."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-5","chapter":3,"topic":"Escrow dan trust","section":"s10","prompt":"Pembeli bersedia membayar jika kondisi barang cocok. Penjual enggan mengirim sebelum kepastian dana. Mekanisme yang paling langsung mengurangi risiko pertukaran berurutan adalah…","reason":"Escrow menahan dan melepaskan dana menurut syarat yang disepakati. Ini mengatasi siapa harus menyerahkan lebih dahulu. Rating membantu kepercayaan sebelum transaksi, tetapi tidak dengan sendirinya mengatur transfer dana saat sengketa.","options":["Escrow dengan bukti penerimaan dan aturan sengketa","Prapembayaran dengan verifikasi identitas penjual","Pascapembayaran dengan rating dan batas kredit","Transfer langsung dengan pelacakan pengiriman"],"analysis":["Dana ditahan pihak perantara dan dilepas berdasarkan syarat pertukaran yang disepakati.","Identitas mengurangi anonimitas, tetapi risiko penyerahan sebelum pemeriksaan tetap ditanggung pembeli.","Memindahkan risiko gagal bayar kepada penjual yang justru menolak mengirim tanpa kepastian dana.","Pelacakan menunjukkan pergerakan, bukan kesesuaian kondisi barang atau mekanisme penahanan dana."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-6","chapter":3,"topic":"Travel online","section":"s5","prompt":"Dua tiket memiliki harga awal sama. Tiket A tidak dapat diubah dan bagasi berbayar; tiket B lebih fleksibel dengan bagasi termasuk. Pembeli sering mengubah jadwal. Dasar perbandingan terbaik adalah…","reason":"Produk travel merupakan janji layanan dengan aturan. Harga awal sama tidak berarti nilai atau biaya total sama. Relevansi fleksibilitas harus dinilai terhadap pola perjalanan pengguna, bukan digeneralisasikan sebagai pilihan terbaik bagi semua.","options":["Harga awal dan biaya perubahan pada satu skenario","Rata-rata biaya penumpang pada seluruh rute","Banyaknya fleksibilitas tanpa menilai pemakaiannya","Biaya total dan ketentuan sesuai pola perjalanan"],"analysis":["Lebih baik daripada harga awal saja, tetapi mengabaikan bagasi dan kemungkinan perubahan yang berbeda.","Rata-rata umum dapat tidak mewakili frekuensi perubahan dan kebutuhan bagasi pengguna ini.","Fleksibilitas merupakan nilai bila sesuai kebutuhan; jumlah opsi saja bukan ukuran biaya total atau kecocokan.","Perubahan jadwal dan bagasi memengaruhi biaya serta manfaat yang relevan bagi pengguna kasus."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-7","chapter":3,"topic":"Online employment","section":"s6","prompt":"Portal kerja menerima tiga kali lebih banyak CV, tetapi proporsi yang lolos asesmen turun. Belum tersedia angka kelulusan absolut atau biaya penyaringan. Evaluasi mana paling tepat?","reason":"Proporsi dan jumlah absolut berbeda. Misalnya 100 CV × 30% menghasilkan 30 kandidat, sedangkan 300 × 20% menghasilkan 60 meski proporsinya turun. Bandingkan kandidat sesuai kriteria dan biaya per kandidat sebelum menyimpulkan kualitas atau efisiensi matching berubah.","options":["Simpulkan matching membaik dari total CV masuk","Bandingkan biaya iklan per CV sebelum dan sesudah","Uji jumlah kandidat layak dan biaya per kandidat","Simpulkan matching memburuk dari rasio kelulusan"],"analysis":["Input yang lebih besar belum membuktikan jumlah atau kualitas hasil dan efisiensi penyaringan.","Ini metrik akuisisi input; biaya per kandidat layak diperlukan untuk menilai hasil matching.","Pisahkan proporsi dari jumlah absolut, lalu ukur efisiensi menyaring kandidat yang benar-benar sesuai.","Rasio turun dapat bersamaan dengan jumlah kandidat layak naik; perlu denominator dan biaya."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-8","chapter":3,"topic":"Personalisasi dan customization","section":"s11","prompt":"Menampilkan produk berdasarkan riwayat pengguna dan membuat sepatu sesuai ukuran pesanan merupakan dua bentuk perubahan yang sama: keduanya hanya personalisasi informasi.","reason":"Rekomendasi mengubah informasi/pengalaman dan merupakan personalisasi. Pembuatan sepatu mengubah produk sehingga merupakan customization. Keduanya dapat digabung, tetapi objek yang diubah berbeda.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Rekomendasi mengubah informasi/pengalaman dan merupakan personalisasi. Pembuatan sepatu mengubah produk sehingga merupakan customization. Keduanya dapat digabung, tetapi objek yang diubah berbeda."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-9","chapter":3,"topic":"Online brokerage","section":"s7","prompt":"Aplikasi trading yang mengirim order secara elektronik masih dapat memerlukan broker serta bursa untuk memproses transaksi.","reason":"Antarmuka elektronik mendigitalkan akses, bukan otomatis menghilangkan seluruh lembaga perantara. Diagram materi menempatkan sistem broker dan koneksi ke bursa di belakang antarmuka pengguna.","options":["Benar","Salah"],"analysis":["Antarmuka elektronik mendigitalkan akses, bukan otomatis menghilangkan seluruh lembaga perantara. Diagram materi menempatkan sistem broker dan koneksi ke bursa di belakang antarmuka pengguna.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-10","chapter":3,"topic":"Flash sales dan kanal","section":"s3","prompt":"Retailer click-and-mortar menjual stok berlebih melalui flash sale daring. Dalam klasifikasi materi, flash sale menjelaskan mekanisme penawaran, sedangkan click-and-mortar menjelaskan struktur kanal.","reason":"Sumbu klasifikasi berbeda dapat berlaku bersama. Batas waktu penawaran menjelaskan flash sale; keberadaan kanal toko fisik dan online menjelaskan click-and-mortar. Perubahan mekanisme promosi tidak menghapus struktur kanal tersebut.","options":["Benar","Salah"],"analysis":["Sumbu klasifikasi berbeda dapat berlaku bersama. Batas waktu penawaran menjelaskan flash sale; keberadaan kanal toko fisik dan online menjelaskan click-and-mortar. Perubahan mekanisme promosi tidak menghapus struktur kanal tersebut.","Menolak klaim ini tidak sesuai mekanisme kasus. Sumbu klasifikasi berbeda dapat berlaku bersama. Batas waktu penawaran menjelaskan flash sale; keberadaan kanal toko fisik dan online menjelaskan click-and-mortar. Perubahan mekanisme promosi tidak menghapus struktur kanal tersebut."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-4-1","chapter":4,"topic":"Sumbu klasifikasi B2B","section":"s2","prompt":"Pabrik membeli pelumas untuk pemeliharaan mesin melalui kontrak tahunan dengan distributor khusus industri. Klasifikasi tujuan barang dan pola pembelian adalah…","reason":"Pelumas yang dipakai merawat mesin tidak masuk langsung ke produk akhir, sehingga termasuk MRO/indirect dalam konteks ini. Kontrak tahunan menunjukkan systematic sourcing. Sektor pemasok merupakan sumbu lain.","options":["Indirect/MRO; spot purchasing","Direct material; systematic sourcing","Indirect/MRO; systematic sourcing","Direct material; spot purchasing"],"analysis":["Tujuan barang benar, tetapi kontrak tahunan menunjukkan pola terencana.","Pola kontrak benar, tetapi tujuan penggunaan bukan bahan langsung.","Tujuan pemeliharaan dan hubungan kontraktual mendukung dua label ini.","Barang tidak menjadi komponen produk dan pembelian tidak insidental."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-2","chapter":4,"topic":"E-tendering vs reverse auction","section":"s7","prompt":"Universitas mengundang proposal implementasi sistem dengan pendekatan teknis berbeda. Evaluasi mencakup integrasi, layanan dan biaya. Menjadikan harga terendah satu-satunya dasar pemenang terutama bermasalah karena…","reason":"Reverse auction paling jelas ketika penawaran dapat dibandingkan terhadap spesifikasi yang setara. Dalam kasus solusi heterogen, harga tidak mewakili seluruh nilai atau risiko. Tender elektronik dapat memakai evaluasi multikriteria tanpa lelang berulang.","options":["Biaya pembelian belum dikonversi menjadi komisi","Solusi belum setara pada dimensi yang dinilai","Jumlah pemasok belum sama dengan jumlah pembeli","Tender elektronik belum mempunyai harga pembuka"],"analysis":["Komisi merupakan model imbalan perantara, bukan prasyarat membandingkan proposal pengadaan.","Harga tidak merangkum perbedaan integrasi, layanan, serta risiko implementasi.","Reverse auction tidak mensyaratkan jumlah kedua sisi sama; satu pembeli dan banyak pemasok justru lazim.","Evaluasi proposal multikriteria tidak memerlukan mekanisme harga pembuka lelang."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-3","chapter":4,"topic":"Total cost of ownership","section":"s6","prompt":"Vendor A menawarkan Rp90 juta dengan operasi tahunan Rp25 juta. Vendor B menawarkan Rp110 juta dengan operasi Rp15 juta. Untuk tiga tahun tanpa diskonto/nilai sisa, pilihan berbasis total biaya adalah…","reason":"Hitung komponen pada horizon yang sama. A = 90 + 3×25 = 165 juta; B = 110 + 3×15 = 155 juta. Harga awal yang lebih murah tidak menjamin total biaya lebih rendah.","options":["B lebih rendah Rp10 juta selama tiga tahun","A lebih rendah Rp20 juta selama tiga tahun","A lebih rendah Rp10 juta selama tiga tahun","B lebih rendah Rp30 juta selama tiga tahun"],"analysis":["Selisih biaya awal tertutup oleh penghematan operasi tiga tahun.","Ini selisih harga awal yang mengabaikan biaya operasi.","A justru memiliki total biaya Rp10 juta lebih tinggi.","Ini penghematan operasi sebelum mengurangi tambahan harga awal B."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-4","chapter":4,"topic":"Desktop vs maverick purchasing","section":"s8","prompt":"Pegawai memesan alat tulis dari katalog kontrak memakai batas anggaran otomatis. Pegawai lain membeli item sama dari situs luar tanpa persetujuan. Pasangan paling tepat adalah…","reason":"Desktop purchasing dapat mendesentralisasikan order sambil mempertahankan kontrol kontrak. Maverick purchasing melewati ketentuan pengadaan. Kedua aktivitas dilakukan individu, tetapi tingkat kepatuhannya berbeda.","options":["Reverse auction; forward auction","Desktop purchasing; maverick purchasing","Maverick purchasing; desktop purchasing","Strategic sourcing; group purchasing"],"analysis":["Tidak ada kompetisi bid pada kedua pembelian tersebut.","Yang pertama terkendali katalog/anggaran; yang kedua melewati prosedur.","Membalik arti kontrol proses yang dijelaskan dalam kasus.","Kasus membahas pelaksanaan order, bukan pemilihan strategi atau agregasi."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-5","chapter":4,"topic":"Vertical vs horizontal exchange","section":"s9","prompt":"Platform mempertemukan perusahaan dari banyak industri untuk membeli perlengkapan kantor. Karakter pasar utamanya adalah…","reason":"Horizontal menjangkau kebutuhan lintas industri, sering untuk input umum seperti MRO. Vertical melayani rantai atau kebutuhan industri tertentu. Jenis barang dan cakupan industri perlu dibedakan dari kepemilikan platform.","options":["Private sell-side karena barangnya terstandar","Buy-side tunggal karena kebutuhan pembeli serupa","Horizontal exchange untuk kebutuhan lintas industri","Vertical exchange karena pembelinya perusahaan"],"analysis":["Standarisasi barang tidak menentukan kepemilikan satu penjual.","Kesamaan kebutuhan tidak berarti hanya ada satu pembeli.","Perlengkapan umum digunakan oleh pembeli dari berbagai sektor.","Status pembeli bisnis tidak menjadikan pasar khusus satu industri."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-6","chapter":4,"topic":"Buying center","section":"s1","prompt":"Dalam pengadaan laptop, laboratorium menyusun spesifikasi, unit pengadaan menegosiasi kontrak, dan pimpinan menyetujui pilihan. Pasangan peran lab dan unit pengadaan adalah…","reason":"Peran buying center ditentukan aktivitas. Lab memengaruhi kriteria teknis; unit pengadaan menangani sourcing/negosiasi. Otoritas keputusan akhir pada pimpinan berbeda dari dua peran tersebut.","options":["Decider dan gatekeeper","Gatekeeper dan user","Buyer dan decider","Influencer dan buyer"],"analysis":["Kasus menempatkan keputusan final pada pimpinan dan tidak menyebut pengendalian akses.","Kedua kegiatan yang disebut bukan pembatasan informasi atau penggunaan akhir.","Menyusun spesifikasi bukan otomatis membeli; negosiasi bukan persetujuan final.","Spesifikasi memengaruhi pilihan; negosiasi/pengadaan merupakan fungsi buyer."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-7","chapter":4,"topic":"Collaborative commerce","section":"s11","prompt":"Pemasok dan produsen berbagi forecast serta menyelaraskan rencana produksi sebelum ada order pembelian. Nilai utama aktivitas tersebut adalah…","reason":"Kolaborasi mengoordinasikan keputusan lintas perusahaan, bukan hanya mengeksekusi transaksi. Berbagi rencana dapat memperbaiki keselarasan pasokan-permintaan. Belum adanya PO tidak membuat kegiatan tersebut berada di luar c-commerce.","options":["Menyelaraskan rencana permintaan dan pasokan","Mengotomasi pencocokan invoice dengan penerimaan","Mengonsolidasikan pembelian untuk diskon volume","Membandingkan bid untuk menentukan harga kontrak"],"analysis":["Kolaborasi praorder menyambungkan forecast dan kapasitas, bukan hanya memproses transaksi yang sudah terjadi.","Pencocokan invoice terjadi setelah order dan penerimaan; tahap yang dibahas adalah perencanaan.","Agregasi order kelompok berbeda dari berbagi forecast dan menyelaraskan rencana dua mitra.","Penemuan harga melalui penawaran bukan kegiatan dominan dalam kasus perencanaan bersama."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-8","chapter":4,"topic":"EDI dan B2B","section":"s1","prompt":"Perusahaan dapat menjalankan B2B tanpa EDI, dan penggunaan EDI menunjukkan mekanisme pertukaran dokumen, bukan dengan sendirinya model pendapatan.","reason":"B2B mengklasifikasikan hubungan organisasi. EDI merupakan salah satu cara dokumen terstruktur dipertukarkan. Model pendapatan tetap perlu dijelaskan terpisah dari sarana komunikasi.","options":["Benar","Salah"],"analysis":["B2B mengklasifikasikan hubungan organisasi. EDI merupakan salah satu cara dokumen terstruktur dipertukarkan. Model pendapatan tetap perlu dijelaskan terpisah dari sarana komunikasi.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-9","chapter":4,"topic":"Group purchasing","section":"s8","prompt":"Dua kelompok memesan total unit yang sama dengan kepastian pembayaran dan biaya distribusi setara. Dalam diskon yang semata-mata berbasis volume, kelompok beranggota lebih banyak memperoleh dasar tawar lebih kuat.","reason":"Unit yang dikomitmenkan sama dan faktor lain dibuat setara. Jumlah anggota tidak menambah volume, sehingga aturan diskon volume tidak memberi keunggulan tambahan. Jika risiko, biaya atau relasi berubah, kasusnya berbeda.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Unit yang dikomitmenkan sama dan faktor lain dibuat setara. Jumlah anggota tidak menambah volume, sehingga aturan diskon volume tidak memberi keunggulan tambahan. Jika risiko, biaya atau relasi berubah, kasusnya berbeda.","Unit yang dikomitmenkan sama dan faktor lain dibuat setara. Jumlah anggota tidak menambah volume, sehingga aturan diskon volume tidak memberi keunggulan tambahan. Jika risiko, biaya atau relasi berubah, kasusnya berbeda."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-10","chapter":4,"topic":"Supply chain dan sistem","section":"s10","prompt":"CRM berfokus pada hubungan pelanggan dan SRM pada pemasok; keduanya dapat berkontribusi pada koordinasi rantai pasok meskipun objek hubungannya berbeda.","reason":"Hubungan pelanggan menyediakan sinyal kebutuhan, sementara pemasok menyediakan kemampuan pasokan. Integrasi informasi membantu koordinasi tanpa menjadikan CRM dan SRM sinonim.","options":["Benar","Salah"],"analysis":["Hubungan pelanggan menyediakan sinyal kebutuhan, sementara pemasok menyediakan kemampuan pasokan. Integrasi informasi membantu koordinasi tanpa menjadikan CRM dan SRM sinonim.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-5-1","chapter":5,"topic":"Kategori e-government","section":"s3","prompt":"Dinas A dan dinas B bertukar data untuk mempercepat verifikasi bantuan. Portal yang sama juga menyediakan penggajian pegawai. Dua fungsi tersebut paling tepat dipetakan sebagai…","reason":"Klasifikasi ditentukan relasi pada fungsi tertentu. Pertukaran antardinas merupakan G2G; layanan langsung kepada pegawai merupakan G2E dan dapat meningkatkan IEE. Satu portal tidak wajib memiliki satu kategori tunggal.","options":["G2C; G2B dengan manfaat IEE","G2E; G2G dengan manfaat G2C","G2B; G2C dengan manfaat G2E","G2G; G2E dengan manfaat IEE"],"analysis":["Data verifikasi ditukar antardinas, bukan langsung dengan warga/bisnis.","Pertukaran antarinstansi bukan layanan pegawai; penggajian bukan antarinstansi.","Tidak ada bisnis pada fungsi pertama atau warga umum pada fungsi kedua.","Membedakan relasi antarlembaga dan pemerintah-pegawai."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-2","chapter":5,"topic":"E-voting","section":"s3","prompt":"Sistem e-voting menghitung suara cepat dan melakukan autentikasi pemilih. Namun tidak tersedia bukti untuk memeriksa ulang hasil penghitungan. Penilaian yang paling tepat adalah…","reason":"Autentikasi dan kecepatan tidak menjamin integritas hasil dapat diverifikasi. Materi menekankan keamanan serta audit. Ketiadaan audit trail yang memadai menyisakan pertanyaan tentang pemeriksaan hasil, bukan membuktikan hasil pasti salah.","options":["Autentikasi harus diulang pada tahap rekapitulasi","Kapasitas hitung harus disetarakan antarperangkat","Ketersediaan server harus menjadi prioritas tunggal","Kemampuan audit hasil belum memadai"],"analysis":["Mengulang pemeriksaan identitas tidak menghasilkan bukti bahwa suara dihitung dengan benar.","Kesetaraan performa tidak menyelesaikan ketiadaan bukti audit; kecepatan pun sudah dinyatakan baik.","Availability penting, tetapi bukti kasus secara spesifik menunjukkan masalah verifikasi hasil.","Tanpa bukti pemeriksaan ulang, autentikasi dan kecepatan tidak membuktikan hasil dapat diaudit."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-3","chapter":5,"topic":"LMS vs KM","section":"s4","prompt":"Universitas ingin mengelola jadwal, penugasan, nilai dan akses modul. Perusahaan mitranya ingin menyimpan solusi teknisi, menemukan pakar dan memakai ulang praktik kerja. Pasangan sistem dominan adalah…","reason":"LMS mengelola proses pembelajaran, sedangkan KM mengelola pengetahuan organisasi. Kedua sistem dapat berbagi konten, tetapi fungsi dominan kasus berbeda. E-learning juga dapat memperbaiki operasi secara tidak langsung.","options":["LMS untuk universitas; ELS saja untuk perusahaan","Repositori untuk universitas; direktori pakar untuk perusahaan","LMS untuk universitas; KM untuk perusahaan","KM untuk universitas; LMS untuk perusahaan"],"analysis":["ELS membantu menemukan pakar, tetapi belum mencakup penyimpanan, validasi, dan reuse seluruh pengetahuan.","Masing-masing hanya komponen; belum mencakup administrasi nilai maupun seluruh siklus pengetahuan.","Administrasi pembelajaran berbeda dari pengelolaan solusi serta keahlian untuk pemakaian organisasi.","Membalik fungsi dominan: jadwal/nilai memerlukan LMS, sedangkan reuse praktik kerja menekankan KM."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-4","chapter":5,"topic":"Knowledge refinement","section":"s5","prompt":"Tim mengambil solusi forum, menguji pada tiga konfigurasi, lalu menambahkan kondisi kapan solusi gagal. Tahap KM yang paling dominan adalah…","reason":"Aktivitas utama adalah memvalidasi serta memberi konteks agar pengetahuan dapat diterapkan dengan tepat. Sumbernya forum tidak menentukan tahap. Ini refinement, meskipun dapat didahului capture dan diikuti dissemination.","options":["Store: mengarsipkan dokumen ke repositori","Disseminate: menyalurkan hasil ke pengguna","Refine: memvalidasi dan memberi konteks","Capture: mencatat pengalaman yang tersedia"],"analysis":["Tidak menjelaskan pengujian dan penambahan syarat penerapan.","Belum ada tindakan distribusi sebagai fokus utama kasus.","Pengujian serta batas penerapan merupakan inti refinement.","Pengambilan awal ada, tetapi kasus menekankan validasi berikutnya."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-5","chapter":5,"topic":"Expert location system","section":"s5","prompt":"Pertanyaan tidak memiliki jawaban cocok dalam repositori. Sistem menemukan teknisi yang relevan dan meminta solusi. Agar pembelajaran organisasi berlanjut, langkah setelah solusi tersedia sebaiknya…","reason":"ELS tidak hanya menghubungkan orang. Solusi perlu ditinjau, disampaikan dan ditambahkan ke repositori agar kasus serupa tidak selalu mengulang pencarian pakar. Validasi menjaga kualitas pengetahuan yang dibagikan.","options":["Tinjau solusi, kirim, dan perbarui repositori","Kirim solusi, tutup tiket, dan perbarui profil pakar","Arsipkan jawaban mentah, lalu tutup akses kasus","Tambahkan kata kunci, lalu arahkan semua kasus ke pakar"],"analysis":["Menutup kasus sekaligus mengubah jawaban pakar menjadi pengetahuan yang dapat dipakai ulang.","Profil membantu pencarian berikutnya, tetapi isi solusi tidak tersedia untuk reuse bila tidak ditangkap.","Penyimpanan tanpa peninjauan dan akses yang sesuai belum membentuk pengetahuan yang dapat digunakan.","Memperbaiki routing, tetapi mempertahankan ketergantungan pada pakar untuk masalah berulang."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-6","chapter":5,"topic":"E-health sebagai sistem","section":"s6","prompt":"Rumah sakit menghubungkan hasil laboratorium dengan rekam pasien dan memberi dokter akses sesuai peran. Tim ingin menguji apakah integrasi memperbaiki koordinasi pelayanan, bukan hanya menambah data. Pasangan manfaat dan indikator mana paling langsung?","reason":"Integrasi membuat hasil pemeriksaan tersedia dalam konteks pasien. Salah satu konsekuensi yang dapat diuji adalah berkurangnya pemeriksaan berulang akibat informasi sebelumnya tidak ditemukan. Tetap periksa alasan klinis, komposisi pasien, dan baseline; tidak semua pemeriksaan ulang merupakan duplikasi yang sia-sia.","options":["Kapasitas pelayanan; evaluasi jumlah akun dokter","Ketepatan klinis; evaluasi jumlah hasil yang diunggah","Efisiensi administrasi; evaluasi kecepatan unduh saja","Kontinuitas informasi; evaluasi duplikasi pemeriksaan"],"analysis":["Akun merupakan kesiapan akses, bukan kapasitas layanan atau bukti informasi dipakai dalam keputusan.","Volume unggahan tidak mengukur ketepatan diagnosis; perlu indikator klinis yang sesuai.","Kecepatan akses dapat membantu, tetapi belum menguji koordinasi pelayanan yang menjadi tujuan integrasi.","Rekam yang terhubung membantu dokter melihat hasil sebelumnya; penurunan tes duplikat menguji penggunaan informasi itu."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-7","chapter":5,"topic":"C2C dan platform","section":"s7","prompt":"Dua individu bertransaksi barang bekas lewat platform yang menyediakan escrow dan mengenakan biaya layanan. Relasi barang dan layanan platform paling tepat dibedakan sebagai…","reason":"Barang tetap dipertukarkan antarindividu, sehingga C2C. Platform menyediakan layanan bisnis yang dapat dibedakan dari relasi barang. Klasifikasi tidak berubah hanya karena pembayaran melalui perantara.","options":["C2C pada barang; intrabusiness pada layanan platform","B2B2C pada barang; B2B pada layanan platform","C2C pada barang; layanan bisnis oleh platform","B2C pada barang; C2C pada layanan platform"],"analysis":["Layanan platform melibatkan pihak luar, bukan proses yang hanya berlangsung di dalam satu organisasi.","Tidak dinyatakan ada dua bisnis dalam rantai penjual barang; penjualnya individu.","Individu bertukar barang, sementara platform menjalankan kegiatan bisnis layanan perantara.","Membalik unit analisis: platform bukan pemilik barang pada fakta kasus."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-8","chapter":5,"topic":"M-government","section":"s3","prompt":"Peringatan bencana dari pemerintah ke ponsel warga dapat sekaligus diklasifikasikan G2C dan m-government.","reason":"G2C menyebut relasi pelakunya, sedangkan m-government menyebut penggunaan kanal/platform mobile. Dua dimensi tersebut dapat berlaku sekaligus pada satu layanan.","options":["Benar","Salah"],"analysis":["G2C menyebut relasi pelakunya, sedangkan m-government menyebut penggunaan kanal/platform mobile. Dua dimensi tersebut dapat berlaku sekaligus pada satu layanan.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-9","chapter":5,"topic":"E-learning dan hasil","section":"s4","prompt":"Dashboard LMS mencatat nilai asesmen praktik dan penyelesaian video secara terpisah. Untuk tujuan mengukur kompetensi melakukan prosedur, completion video merupakan pengganti yang setara dengan asesmen praktik.","reason":"Completion membuktikan aktivitas penyelesaian konten, sedangkan asesmen praktik menguji penerapan prosedur. Kedua metrik dapat saling melengkapi, tetapi kesetaraan validitasnya tidak mengikuti dari keduanya berada di LMS.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Completion membuktikan aktivitas penyelesaian konten, sedangkan asesmen praktik menguji penerapan prosedur. Kedua metrik dapat saling melengkapi, tetapi kesetaraan validitasnya tidak mengikuti dari keduanya berada di LMS.","Completion membuktikan aktivitas penyelesaian konten, sedangkan asesmen praktik menguji penerapan prosedur. Kedua metrik dapat saling melengkapi, tetapi kesetaraan validitasnya tidak mengikuti dari keduanya berada di LMS."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-10","chapter":5,"topic":"E-books dan perangkat","section":"s4","prompt":"Dua perangkat membuka berkas e-book yang sama. Keberhasilan membuka teks memberikan dasar yang cukup untuk menyatakan dukungan video dan interaktivitas keduanya setara.","reason":"Kompatibilitas teks berbeda dari kemampuan merender multimedia, menjalankan interaksi, atau terhubung untuk pembaruan. Kesetaraan harus diuji untuk fitur yang diklaim, bukan disimpulkan dari satu kemampuan dasar.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Kompatibilitas teks berbeda dari kemampuan merender multimedia, menjalankan interaksi, atau terhubung untuk pembaruan. Kesetaraan harus diuji untuk fitur yang diklaim, bukan disimpulkan dari satu kemampuan dasar.","Kompatibilitas teks berbeda dari kemampuan merender multimedia, menjalankan interaksi, atau terhubung untuk pembaruan. Kesetaraan harus diuji untuk fitur yang diklaim, bukan disimpulkan dari satu kemampuan dasar."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"exam-1-1","chapter":1,"topic":"Kanal, digitasi, dan revenue stream","section":"s9","prompt":"Penerbit menutup toko retailnya, menjual buku cetak melalui web, dan mengirim lewat kurir. Ia juga menerima langganan akses e-book secara online. Klasifikasi mana konsisten untuk organisasi, transaksi buku cetak, dan penerimaan e-book?","reason":"Pisahkan tiga unit analisis. Kanal retail online sesuai pure-play; buku cetak tetap partial EC karena pemenuhan/pengirimannya fisik. Pembayaran periodik akses e-book adalah subscription revenue. Gudang tidak sama dengan toko retail, dan transaksi campuran tidak mengubah subscription menjadi transaction fee.","options":["Pure-play; pure EC; subscription revenue","Click-and-mortar; partial EC; subscription revenue","Pure-play; partial EC; transaction-fee revenue","Click-and-mortar; pure EC; transaction-fee revenue","Pure-play; partial EC; subscription revenue"],"analysis":["Pure-play benar, tetapi kanal online tidak mendigitalkan pengiriman buku cetak.","Gudang bukan bukti bahwa kanal toko retail fisik masih ada.","Subscription menagih akses periodik, sedangkan transaction fee menagih transaksi tertentu.","Mencampurkan operasi fisik, kanal online, dan penagihan periodik.","Label diterapkan pada kanal organisasi, digitalisasi transaksi, lalu cara menerima pendapatan."],"answer":4,"type":"mc","pool":"exam","source":"Chapter 1: slide S1 dan buku B1; kasus baru dalam cakupan bab."},{"id":"exam-1-2","chapter":1,"topic":"Canvas dan janji layanan","section":"s8","prompt":"Platform menjanjikan laboratorium kampus “reagen sesuai spesifikasi, tersedia besok”. Penjual mengunggah sertifikat sendiri; stok diperbarui mingguan. Pasangan key activities dan key resources mana paling langsung menguji kemampuan memenuhi value proposition tersebut?","reason":"Janji memiliki dua syarat: kesesuaian spesifikasi dan ketersediaan tepat waktu. Validasi serta reservasi perlu ditopang data mutu dan stok yang dapat dipercaya. Akuisisi atau rancangan pendapatan relevan dalam canvas, tetapi tidak menguji kemampuan operasi memenuhi kedua syarat itu.","options":["Penyusunan katalog dan desain; foto serta deskripsi item","Validasi sertifikat dan reservasi; data mutu serta stok","Negosiasi komisi dan penagihan; kontrak serta piutang","Akuisisi penjual dan promosi; daftar prospek serta kanal","Segmentasi pembeli dan survei; profil serta umpan balik"],"analysis":["Mendukung penyajian penawaran; sertifikat dan stok masih perlu diverifikasi.","Aktivitas dan sumber daya langsung menopang dua komponen janji layanan.","Menguji penerimaan dan kontrak, belum spesifikasi atau kesiapan stok.","Menguji pertumbuhan, tetapi banyak penjual tidak menjamin stok benar.","Menguji kecocokan janji dengan kebutuhan pasar, belum kemampuan melaksanakannya."],"answer":1,"type":"mc","pool":"exam","source":"Chapter 1: slide S1 dan buku B1; kasus baru dalam cakupan bab."},{"id":"exam-1-3","chapter":1,"topic":"Pendapatan platform dan nilai transaksi","section":"s9","prompt":"Platform tidak memiliki barang yang dijual. Transaksi penjual mencapai Rp80 juta per bulan. Platform menerima komisi 6% dan langganan 20 toko masing-masing Rp150.000. Biaya variabel platform Rp2 juta. Abaikan pajak, refund, dan biaya tetap. Berapa pendapatan serta kontribusi platform?","reason":"GMV Rp80 juta adalah nilai barang para penjual. Komisi = 0,06 × 80 juta = 4,8 juta; subscription = 20 × 150 ribu = 3 juta. Pendapatan 7,8 juta dikurangi biaya variabel 2 juta menghasilkan kontribusi 5,8 juta, sebelum biaya tetap.","options":["Pendapatan Rp4,8 juta; kontribusi Rp2,8 juta","Pendapatan Rp7,8 juta; kontribusi Rp4,8 juta","Pendapatan Rp5,8 juta; kontribusi Rp3,8 juta","Pendapatan Rp7,8 juta; kontribusi Rp5,8 juta","Pendapatan Rp83 juta; kontribusi Rp81 juta"],"analysis":["Menghitung komisi tetapi mengabaikan pendapatan langganan.","Pendapatan tepat, tetapi mengurangkan langganan seolah biaya.","Menamai kontribusi sebagai pendapatan lalu mengurangkan biaya variabel lagi.","Memisahkan dua revenue streams dari GMV lalu mengurangkan biaya variabel satu kali.","Memasukkan nilai barang penjual sebagai pendapatan platform penuh."],"answer":3,"type":"mc","pool":"exam","source":"Chapter 1: slide S1 dan buku B1; kasus baru dalam cakupan bab."},{"id":"exam-1-4","chapter":1,"topic":"Relasi aktor dan perantara","section":"s3","prompt":"Marketplace mengatur pembayaran jual beli kamera pribadi antara dua individu tanpa membeli kameranya. Pada unit analisis pertukaran kamera, biaya layanan marketplace mengubah relasi C2C menjadi B2C.","reason":"Pelaku pertukaran kamera tetap dua individu. Biaya platform menunjukkan transaksi jasa perantara yang perlu dianalisis terpisah; itu tidak membuat platform menjadi penjual kamera. B2C pada barang memerlukan bisnis bertindak sebagai penjualnya.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Pelaku pertukaran kamera tetap dua individu. Biaya platform menunjukkan transaksi jasa perantara yang perlu dianalisis terpisah; itu tidak membuat platform menjadi penjual kamera. B2C pada barang memerlukan bisnis bertindak sebagai penjualnya."],"answer":1,"type":"tf","pool":"exam","source":"Chapter 1: slide S1 dan buku B1; kasus baru dalam cakupan bab."},{"id":"exam-1-5","chapter":1,"topic":"Richness dan reach","section":"s5","prompt":"Katalog tetap melayani pengguna dan SKU yang sama, tetapi menambahkan spesifikasi kompatibilitas dan demonstrasi penggunaan. Richness meningkat meskipun perluasan reach belum ditunjukkan.","reason":"Richness berkaitan dengan kedalaman dan mutu informasi. Reach berkaitan dengan jangkauan pihak atau penawaran. Kasus menahan jangkauan tetap; peningkatan informasi tidak perlu dinyatakan sebagai perluasan reach agar bermanfaat.","options":["Benar","Salah"],"analysis":["Richness berkaitan dengan kedalaman dan mutu informasi. Reach berkaitan dengan jangkauan pihak atau penawaran. Kasus menahan jangkauan tetap; peningkatan informasi tidak perlu dinyatakan sebagai perluasan reach agar bermanfaat.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Chapter 1: slide S1 dan buku B1; kasus baru dalam cakupan bab."},{"id":"exam-1-6","chapter":1,"topic":"EB dan aktivitas internal","section":"s1","prompt":"Perusahaan mendigitalkan pelatihan teknisi dan berbagi desain dengan pemasok, sedangkan penjualan pelanggan masih offline. Dengan definisi EB luas dalam materi, dua aktivitas digital tersebut termasuk e-business.","reason":"EB mencakup pembelajaran, kolaborasi mitra dan operasi organisasi, selain transaksi penjualan. Kanal penjualan offline tidak menghapus kegiatan EB tersebut. Gunakan definisi yang dinyatakan soal, karena EC dalam penggunaan luas kadang mendekati EB.","options":["Benar","Salah"],"analysis":["EB mencakup pembelajaran, kolaborasi mitra dan operasi organisasi, selain transaksi penjualan. Kanal penjualan offline tidak menghapus kegiatan EB tersebut. Gunakan definisi yang dinyatakan soal, karena EC dalam penggunaan luas kadang mendekati EB.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Chapter 1: slide S1 dan buku B1; kasus baru dalam cakupan bab."},{"id":"exam-2-1","chapter":2,"topic":"Struktur pasar dan aturan lelang","section":"s8","prompt":"Situs milik produsen menawarkan satu mesin kepada banyak calon pembeli. Harga diturunkan bertahap dari Rp70 juta; penerima pertama menang. Kombinasi pengendali pasar, sisi pasar, dan aturan harga mana paling tepat?","reason":"Kendali satu produsen menunjukkan private marketplace; satu penjual menghadapi banyak pembeli menunjukkan sell-side. Harga turun sampai diterima adalah Dutch auction. Reverse auction ditentukan pemasok yang bersaing untuk satu pembeli, bukan sekadar arah harga.","options":["Private sell-side; Dutch auction","Private buy-side; reverse auction","Public sell-side; Dutch auction","Private sell-side; reverse auction","Public many-to-many; double auction"],"analysis":["Memakai bukti pengendali, struktur pelaku, dan aturan penawaran secara terpisah.","Harga turun tidak menjadikan produsen pembeli atau calon pembeli pemasok.","Aturan tepat, tetapi banyak pengunjung tidak mengubah kendali satu produsen.","Struktur tepat, tetapi pembeli berebut barang satu penjual dalam kasus ini.","Tidak ada banyak penjual atau pencocokan dua kumpulan bid jual-beli."],"answer":0,"type":"mc","pool":"exam","source":"Chapter 2: slide S2 dan buku B2; kasus baru dalam cakupan bab."},{"id":"exam-2-2","chapter":2,"topic":"Biaya penny auction","section":"s8","prompt":"Setiap bid pada penny auction berbiaya Rp4.000 dan tidak dikembalikan. Rani mengajukan 18 bid lalu menang dengan harga Rp120.000 dan ongkir Rp20.000. Tidak ada biaya lain. Barang setara di toko berharga total Rp200.000. Evaluasi biaya yang benar adalah…","reason":"Biaya bid = 18 × 4.000 = 72.000. Total = 72.000 + 120.000 + 20.000 = 212.000. Dibanding alternatif 200.000, Rani membayar 12.000 lebih banyak. Harga penutup lelang saja mengabaikan biaya partisipasi yang tidak dikembalikan.","options":["Total Rp196.000; lebih murah Rp4.000","Total Rp232.000; lebih mahal Rp32.000","Total Rp212.000; lebih mahal Rp12.000","Total Rp140.000; lebih murah Rp60.000","Total Rp192.000; lebih murah Rp8.000"],"analysis":["Jumlah ini menghitung 14 bid, bukan 18 bid yang dinyatakan.","Menghitung ongkir dua kali, padahal hanya dikenakan satu kali.","Memasukkan semua biaya dan membandingkan total pada basis yang sama.","Mengabaikan 18 biaya bid yang tetap dibayar pemenang.","Memasukkan bid serta harga kemenangan tetapi mengabaikan ongkir."],"answer":2,"type":"mc","pool":"exam","source":"Chapter 2: slide S2 dan buku B2; kasus baru dalam cakupan bab."},{"id":"exam-2-3","chapter":2,"topic":"Crowdsourcing dan seleksi","section":"s11","prompt":"Ide A mendapat suara terbanyak tetapi prototipenya melewati batas biaya. Ide B memenuhi batas biaya dan performa, namun kalah suara. Penyelenggara sejak awal mensyaratkan kelayakan teknis dan memakai voting sebagai masukan. Keputusan paling konsisten adalah…","reason":"Voting menggambarkan preferensi peserta, sedangkan pengujian prototipe membuktikan kelayakan terhadap batas. B dapat diprioritaskan; A dapat diberi kesempatan revisi jika diizinkan. Mengganti syarat kelayakan dengan popularitas sesudah voting mengubah dasar seleksi.","options":["Prioritaskan A; pakai suara untuk mengganti uji biaya","Ambil biaya rata-rata A dan B; luluskan keduanya","Pilih keduanya bergiliran; uji kelayakan setelah rilis","Ulangi voting; gunakan hasilnya sebagai uji teknis","Prioritaskan B; minta revisi A bila aturan mengizinkan"],"analysis":["Mengubah voting menjadi pengganti syarat teknis yang telah diumumkan.","Biaya satu ide tidak dikurangi kelayakan ide lain jika tiap ide harus memenuhi batas.","Menunda syarat wajib sampai sesudah keputusan implementasi.","Voting tambahan tetap mengukur pilihan, bukan perubahan biaya atau performa.","Menjaga batas wajib sekaligus memanfaatkan kontribusi peserta."],"answer":4,"type":"mc","pool":"exam","source":"Chapter 2: slide S2 dan buku B2; kasus baru dalam cakupan bab."},{"id":"exam-2-4","chapter":2,"topic":"Perubahan fungsi perantara","section":"s5","prompt":"Produsen melewati distributor yang semula mencari pembeli dan menangani pengiriman. Platform baru mengambil alih kedua fungsi itu. Disintermediation distributor dan reintermediation fungsi dapat terjadi dalam perubahan rantai yang sama.","reason":"Perantara yang hilang berbeda dari fungsi yang tetap dibutuhkan. Distributor dihapus, sementara platform menjadi perantara baru untuk matching dan fulfillment. Kedua konsep berlaku pada tingkat analisis yang dijelaskan tanpa saling meniadakan.","options":["Benar","Salah"],"analysis":["Perantara yang hilang berbeda dari fungsi yang tetap dibutuhkan. Distributor dihapus, sementara platform menjadi perantara baru untuk matching dan fulfillment. Kedua konsep berlaku pada tingkat analisis yang dijelaskan tanpa saling meniadakan.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Chapter 2: slide S2 dan buku B2; kasus baru dalam cakupan bab."},{"id":"exam-2-5","chapter":2,"topic":"Pencarian visual dan AR","section":"s10","prompt":"Aplikasi menerima foto ruang tamu, mengenali warna, lalu menampilkan daftar sofa di halaman katalog terpisah. Karena foto dunia nyata menjadi masukan, fitur ini diklasifikasikan sebagai augmented reality.","reason":"Gambar dapat menjadi masukan pencarian atau rekomendasi visual. AR menambahkan elemen digital pada pandangan lingkungan nyata; kasus hanya menghasilkan daftar katalog terpisah. Jenis input saja tidak membuktikan representasi AR.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Gambar dapat menjadi masukan pencarian atau rekomendasi visual. AR menambahkan elemen digital pada pandangan lingkungan nyata; kasus hanya menghasilkan daftar katalog terpisah. Jenis input saja tidak membuktikan representasi AR."],"answer":1,"type":"tf","pool":"exam","source":"Chapter 2: slide S2 dan buku B2; kasus baru dalam cakupan bab."},{"id":"exam-2-6","chapter":2,"topic":"Storefront dan mall","section":"s6","prompt":"Direktori mengumpulkan tautan 60 toko dan meneruskan pengguna ke checkout tiap toko. Dalam klasifikasi buku, direktori itu menjadi satu storefront karena tidak memiliki keranjang bersama.","reason":"Referring mall dapat mengumpulkan banyak toko tanpa checkout terpadu. Storefront merujuk toko satu penjual/perusahaan. Kepemilikan keranjang bukan pembeda tunggal; banyak toko tetap dihimpun walaupun transaksi diselesaikan pada situs masing-masing.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Referring mall dapat mengumpulkan banyak toko tanpa checkout terpadu. Storefront merujuk toko satu penjual/perusahaan. Kepemilikan keranjang bukan pembeda tunggal; banyak toko tetap dihimpun walaupun transaksi diselesaikan pada situs masing-masing."],"answer":1,"type":"tf","pool":"exam","source":"Chapter 2: slide S2 dan buku B2; kasus baru dalam cakupan bab."},{"id":"exam-3-1","chapter":3,"topic":"Konflik kanal dan insentif","section":"s11","prompt":"Dealer memberi konsultasi dan uji produk. Pelanggan memakai kode konsultasi untuk membeli di web produsen. Harga akhir kedua kanal sudah sama, tetapi dealer tidak memperoleh imbalan atas pembelian web. Intervensi apa paling langsung menyasar konflik yang tersisa?","reason":"Perbedaan harga telah dihilangkan. Dealer masih menanggung biaya layanan yang menciptakan penjualan pada kanal lain. Kode konsultasi memberi jejak kontribusi sehingga imbalan dapat mengikuti layanan yang berperan, dengan verifikasi untuk mencegah atribusi palsu.","options":["Gabungkan omzet tanpa mencatat asal konsultasi","Bagikan imbalan menurut konsultasi yang terverifikasi","Perbarui harga katalog kedua kanal lebih sering","Pisahkan katalog web dari katalog milik dealer","Nilai dealer hanya dari transaksi di tokonya"],"analysis":["Menghapus jejak yang diperlukan untuk membagi imbalan menurut kontribusi.","Menghubungkan kontribusi dealer dengan nilai transaksi lintas kanal.","Harga akhir sudah sama; frekuensi pembaruan tidak memberi kompensasi layanan.","Pemisahan katalog belum mengubah pihak yang membiayai konsultasi.","Tetap mengabaikan kontribusi dealer pada transaksi web."],"answer":1,"type":"mc","pool":"exam","source":"Chapter 3: slide S3 dan buku B3; kasus baru dalam cakupan bab."},{"id":"exam-3-2","chapter":3,"topic":"Efisiensi pasar kerja online","section":"s6","prompt":"Sebelum perubahan matching, portal menerima 200 CV, 25% lolos asesmen, dengan biaya penyaringan Rp5 juta. Sesudahnya: 500 CV, 16% lolos, biaya Rp6 juta. Kriteria asesmen tetap. Pasangan jumlah hasil dan biaya per kandidat lolos yang tepat adalah…","reason":"Sebelum: 200 × 25% = 50 kandidat; biaya 5 juta/50 = 100 ribu. Sesudah: 500 × 16% = 80 kandidat; biaya 6 juta/80 = 75 ribu. Rasio turun tetapi jumlah lolos naik dan biaya unit turun. Kualitas kerja setelah direkrut belum diukur sehingga tidak boleh disimpulkan dari data ini.","options":["Kandidat lolos naik 30; biaya per kandidat naik 20%","Kandidat lolos naik 60; biaya per kandidat turun 25%","Kandidat lolos tetap 50; biaya per kandidat naik 20%","Kandidat lolos naik 30; biaya per kandidat turun 25%","Kandidat lolos turun 9; biaya per kandidat naik 20%"],"analysis":["Jumlah benar; biaya unit harus dibagi dengan jumlah lolos yang berubah.","Kenaikan adalah 30 orang; angka 60 merupakan persentase kenaikan, bukan orang.","Mengabaikan 500 × 16% = 80 sehingga denominator biaya unit salah.","Jumlah naik dari 50 ke 80 dan biaya unit turun dari 100 ribu ke 75 ribu.","Menyamakan selisih persentase dengan jumlah, lalu biaya total dengan biaya unit."],"answer":3,"type":"mc","pool":"exam","source":"Chapter 3: slide S3 dan buku B3; kasus baru dalam cakupan bab."},{"id":"exam-3-3","chapter":3,"topic":"Produk travel dan biaya relevan","section":"s5","prompt":"Tiket A Rp800.000, bagasi Rp150.000, dan perubahan jadwal Rp300.000. Tiket B Rp1.000.000 termasuk bagasi dan satu perubahan. Pelanggan pasti memakai bagasi dan tepat sekali mengubah jadwal. Tidak ada selisih tarif atau biaya lain. Perbandingan yang benar adalah…","reason":"Bandingkan bundel layanan yang dibutuhkan. A = 800.000 + 150.000 + 300.000 = 1.250.000; B = 1.000.000. B lebih rendah 250.000 untuk kasus ini. Kesimpulan bergantung pada asumsi bagasi dan perubahan, bukan klaim satu tiket selalu lebih baik bagi semua orang.","options":["B lebih rendah Rp250.000 untuk kebutuhan tersebut","A lebih rendah Rp200.000 untuk kebutuhan tersebut","A lebih rendah Rp50.000 untuk kebutuhan tersebut","B lebih rendah Rp100.000 untuk kebutuhan tersebut","B lebih rendah Rp400.000 untuk kebutuhan tersebut"],"analysis":["Membandingkan alternatif setelah semua layanan yang akan digunakan diperhitungkan.","Hanya memakai harga awal dan mengabaikan dua tambahan yang pasti digunakan.","Menghitung bagasi tetapi mengabaikan satu perubahan jadwal.","Menghitung perubahan tetapi mengabaikan bagasi yang dibutuhkan.","Menambahkan biaya yang tidak dinyatakan sehingga selisih terlalu besar."],"answer":0,"type":"mc","pool":"exam","source":"Chapter 3: slide S3 dan buku B3; kasus baru dalam cakupan bab."},{"id":"exam-3-4","chapter":3,"topic":"Omnichannel dan multichannel","section":"s3","prompt":"Retailer memakai satu merek dan katalog pada web serta toko. Order, stok, dan retur tetap terpisah. Keseragaman katalog cukup untuk menyatakan pengalaman pembelian sudah terintegrasi secara omnichannel.","reason":"Merek dan katalog menyatukan komunikasi, tetapi pengalaman lintas kanal memerlukan kesinambungan proses. Order, stok, dan retur yang terpisah menunjukkan fragmentasi. Multichannel menjelaskan keberadaan beberapa kanal; integrasi omnichannel tidak terbukti dari tampilan seragam.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Merek dan katalog menyatukan komunikasi, tetapi pengalaman lintas kanal memerlukan kesinambungan proses. Order, stok, dan retur yang terpisah menunjukkan fragmentasi. Multichannel menjelaskan keberadaan beberapa kanal; integrasi omnichannel tidak terbukti dari tampilan seragam."],"answer":1,"type":"tf","pool":"exam","source":"Chapter 3: slide S3 dan buku B3; kasus baru dalam cakupan bab."},{"id":"exam-3-5","chapter":3,"topic":"Personalisasi dan customization","section":"s11","prompt":"Toko menyusun urutan katalog dari riwayat pembeli, lalu memproduksi jaket mengikuti ukuran yang dimasukkan pembeli. Perubahan pertama mengenai pengalaman informasi, sedangkan perubahan kedua mengenai produk yang dipenuhi.","reason":"Urutan katalog merupakan personalization informasi. Produksi sesuai ukuran mengubah spesifikasi barang sehingga termasuk customization. Keduanya dapat berlangsung dalam satu transaksi, tetapi memerlukan data dan kemampuan operasi yang berbeda.","options":["Benar","Salah"],"analysis":["Urutan katalog merupakan personalization informasi. Produksi sesuai ukuran mengubah spesifikasi barang sehingga termasuk customization. Keduanya dapat berlangsung dalam satu transaksi, tetapi memerlukan data dan kemampuan operasi yang berbeda.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Chapter 3: slide S3 dan buku B3; kasus baru dalam cakupan bab."},{"id":"exam-3-6","chapter":3,"topic":"Broker elektronik dan institusi pasar","section":"s7","prompt":"Pengguna online brokerage mengirim order sendiri melalui aplikasi, tetapi broker meneruskannya ke bursa. Self-service pada antarmuka dan keberadaan perantara institusional dapat berlangsung bersamaan.","reason":"Self-service menjelaskan siapa memasukkan instruksi; broker dan bursa menjalankan fungsi pemrosesan serta pasar. Digitalisasi interaksi bukan bukti seluruh perantara hilang. Analisis harus mengikuti order dari antarmuka hingga penyelesaiannya.","options":["Benar","Salah"],"analysis":["Self-service menjelaskan siapa memasukkan instruksi; broker dan bursa menjalankan fungsi pemrosesan serta pasar. Digitalisasi interaksi bukan bukti seluruh perantara hilang. Analisis harus mengikuti order dari antarmuka hingga penyelesaiannya.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Chapter 3: slide S3 dan buku B3; kasus baru dalam cakupan bab."},{"id":"exam-4-1","chapter":4,"topic":"Total cost of ownership","section":"s6","prompt":"Dua pemasok memenuhi spesifikasi identik. A: Rp100 juta di awal, operasi Rp18 juta per tahun, migrasi keluar Rp12 juta. B: Rp118 juta di awal, operasi Rp12 juta per tahun, tanpa biaya migrasi keluar. Horizon tiga tahun, migrasi terjadi di akhir. Abaikan diskonto dan nilai sisa. Keputusan biaya yang tepat adalah…","reason":"A = 100 + 3×18 + 12 = 166 juta. B = 118 + 3×12 = 154 juta. B lebih murah 12 juta. Seluruh komponen harus memakai horizon yang sama; biaya keluar tidak boleh hilang dari perhitungan. Karena spesifikasi setara, pemilihan berbasis komponen biaya yang diberikan dapat dilakukan.","options":["Pilih B; totalnya lebih rendah Rp30 juta","Pilih A; totalnya lebih rendah Rp6 juta","Pilih B; totalnya lebih rendah Rp12 juta","Pilih A; biaya awalnya lebih rendah Rp18 juta","Keduanya setara; total masing-masing Rp154 juta"],"analysis":["Selisih ini tidak mengikuti penjumlahan komponen pada horizon yang sama.","Perhitungan ini mengubah periode atau biaya yang diberikan.","Memasukkan investasi, tiga tahun operasi dan biaya migrasi yang dinyatakan.","Membatasi perbandingan pada pembelian dan mengabaikan masa pemakaian.","A hanya menjadi 154 juta jika biaya migrasi 12 juta diabaikan."],"answer":2,"type":"mc","pool":"exam","source":"Chapter 4: slide S4 dan buku B4; kasus baru dalam cakupan bab."},{"id":"exam-4-2","chapter":4,"topic":"Group purchasing dan biaya pengadaan","section":"s8","prompt":"Empat laboratorium masing-masing memesan 25 unit. Harga terpisah Rp500.000 per unit. Komitmen gabungan 100 unit mendapat harga Rp460.000, dengan koordinasi Rp2 juta dan distribusi tambahan Rp10.000 per unit. Tidak ada perbedaan lain. Nilai ekonomis penggabungan adalah…","reason":"Terpisah = 100 × 500.000 = 50 juta. Gabungan = 100 × 460.000 + 2 juta + 100 × 10.000 = 49 juta. Penghematan bersih 1 juta, bukan diskon kotor 4 juta. Hasil agregasi ditentukan komitmen unit dan biaya tambahan, bukan jumlah anggota semata.","options":["Hemat Rp4 juta setelah biaya tambahan","Hemat Rp2 juta setelah biaya tambahan","Hemat Rp3 juta setelah biaya tambahan","Lebih mahal Rp1 juta setelah biaya tambahan","Hemat Rp1 juta setelah biaya tambahan"],"analysis":["Ini baru diskon barang; kedua biaya kelompok belum dihitung.","Memasukkan koordinasi tetapi mengabaikan distribusi tambahan 1 juta.","Memasukkan distribusi tetapi mengabaikan koordinasi 2 juta.","Tanda perubahan terbalik: 49 juta tetap di bawah 50 juta.","Mengurangkan koordinasi dan distribusi dari diskon kotor 4 juta."],"answer":4,"type":"mc","pool":"exam","source":"Chapter 4: slide S4 dan buku B4; kasus baru dalam cakupan bab."},{"id":"exam-4-3","chapter":4,"topic":"Exchange dan pola sourcing","section":"s9","prompt":"Operator independen mempertemukan banyak pemasok bahan baku dan banyak pabrik farmasi. Sebagian pembelian melalui kontrak tahunan, sebagian mendadak. Operator bukan satu-satunya pembeli. Struktur pasar dan pola sourcing yang tepat adalah…","reason":"Banyak penjual-pembeli dengan operator independen menunjukkan public exchange. Fokus satu industri menunjukkan vertical exchange. Spot dan systematic sourcing merupakan sumbu pembelian yang dapat hadir bersama; kontrak tahunan tidak membuat operator menjadi buy-side tunggal.","options":["Public vertical exchange; seluruh transaksi harus spot","Public vertical exchange; dua pola sourcing dapat hadir","Private buy-side; kontrak tahunan menentukan pemiliknya","Public horizontal exchange; banyak pabrik berarti lintas industri","Private sell-side; banyak pemasok memakai satu situs"],"analysis":["Vertical tidak melarang kontrak tahunan atau mengubahnya menjadi pembelian spot.","Memisahkan struktur, fokus industri, dan keteraturan pembelian.","Kontrak tidak mengubah banyak pabrik menjadi satu pembeli.","Banyak organisasi tetap bisa berada dalam satu industri, yaitu farmasi.","Satu situs tidak sama dengan pengendalian oleh satu pemasok."],"answer":1,"type":"mc","pool":"exam","source":"Chapter 4: slide S4 dan buku B4; kasus baru dalam cakupan bab."},{"id":"exam-4-4","chapter":4,"topic":"Direct material dan systematic sourcing","section":"s2","prompt":"Pabrik membeli bahan yang masuk ke produk akhir melalui kontrak tahunan. Kontrak menjelaskan systematic sourcing, sedangkan penggunaan bahan dalam produk akhir menjelaskan direct material.","reason":"Tujuan penggunaan dan pola pembelian adalah dua sumbu. Direct/indirect ditentukan peran barang dalam operasi atau produk; systematic/spot ditentukan pola kebutuhan dan pengadaan. Kontrak jangka panjang tidak mengubah bahan langsung menjadi MRO.","options":["Benar","Salah"],"analysis":["Tujuan penggunaan dan pola pembelian adalah dua sumbu. Direct/indirect ditentukan peran barang dalam operasi atau produk; systematic/spot ditentukan pola kebutuhan dan pengadaan. Kontrak jangka panjang tidak mengubah bahan langsung menjadi MRO.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Chapter 4: slide S4 dan buku B4; kasus baru dalam cakupan bab."},{"id":"exam-4-5","chapter":4,"topic":"Desktop purchasing dan kendali","section":"s8","prompt":"Pegawai memesan melalui katalog kontrak dengan limit dan otorisasi yang telah disetujui. Karena unit pembelian tidak mengetik setiap order, aktivitas tersebut tergolong maverick purchasing.","reason":"Desktop purchasing memungkinkan pemesan membeli dalam kontrol dan kontrak yang disetujui. Maverick purchasing menyimpang dari kebijakan atau pengaturan tersebut. Tidak terlibatnya staf pengadaan dalam setiap klik bukan bukti penyimpangan.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Desktop purchasing memungkinkan pemesan membeli dalam kontrol dan kontrak yang disetujui. Maverick purchasing menyimpang dari kebijakan atau pengaturan tersebut. Tidak terlibatnya staf pengadaan dalam setiap klik bukan bukti penyimpangan."],"answer":1,"type":"tf","pool":"exam","source":"Chapter 4: slide S4 dan buku B4; kasus baru dalam cakupan bab."},{"id":"exam-4-6","chapter":4,"topic":"EDI dan perencanaan kolaboratif","section":"s11","prompt":"Dua perusahaan mengirim purchase order elektronik berformat standar, tetapi tidak berbagi forecast atau menyelaraskan rencana. Pertukaran dokumen itu saja cukup untuk menyatakan perencanaan permintaan mereka sudah kolaboratif.","reason":"EDI mendukung pertukaran dokumen terstruktur dan mengurangi entri ulang. Perencanaan kolaboratif memerlukan berbagi dan menyelaraskan keputusan yang belum terjadi pada kasus. Teknologi pertukaran dapat mendukung koordinasi, tetapi bukan bukti hasil koordinasi.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","EDI mendukung pertukaran dokumen terstruktur dan mengurangi entri ulang. Perencanaan kolaboratif memerlukan berbagi dan menyelaraskan keputusan yang belum terjadi pada kasus. Teknologi pertukaran dapat mendukung koordinasi, tetapi bukan bukti hasil koordinasi."],"answer":1,"type":"tf","pool":"exam","source":"Chapter 4: slide S4 dan buku B4; kasus baru dalam cakupan bab."},{"id":"exam-5-1","chapter":5,"topic":"Peran G2G, G2C dan G2E","section":"s3","prompt":"Platform memiliki tiga alur: (X) dinas kesehatan memadankan data dengan dinas sosial; (Y) warga memeriksa status bantuannya; (Z) pegawai dinas mengakses tunjangan kerja. Klasifikasi berdasarkan peran setiap alur adalah…","reason":"X menghubungkan dua instansi sehingga G2G; Y melayani warga sehingga G2C; Z melayani pegawai dalam hubungan kerja sehingga G2E. Ketiganya dapat berada pada satu aplikasi. Identitas umum seseorang atau hosting aplikasi tidak menggantikan peran pada interaksi.","options":["X G2G; Y G2E; Z G2C","X G2C; Y G2C; Z G2E","X G2G; Y G2C; Z G2C","X G2G; Y G2C; Z G2E","X G2E; Y G2C; Z G2G"],"analysis":["Menukar peran warga penerima bantuan dengan pegawai penerima tunjangan kerja.","Tujuan akhir membantu warga tidak mengubah pertukaran antardinas menjadi layanan langsung G2C.","Pegawai juga warga, tetapi Z melayaninya secara eksplisit dalam hubungan kerja.","Klasifikasi mengikuti pasangan pelaku dan peran penerima layanan.","X bukan kepegawaian, dan Z tidak menghubungkan dua instansi sebagai aktor."],"answer":3,"type":"mc","pool":"exam","source":"Chapter 5: slide S5 dan buku B5; kasus baru dalam cakupan bab."},{"id":"exam-5-2","chapter":5,"topic":"ELS dan siklus pengetahuan","section":"s5","prompt":"ELS menemukan pakar setelah repositori tidak memiliki solusi. Pakar menjawab dan masalah selesai, tetapi kasus serupa terus dirutekan ke pakar yang sama. Perbaikan paling langsung untuk mengurangi pengulangan sekaligus menjaga validasi adalah…","reason":"Routing sudah bekerja; jawabannya belum menjadi pengetahuan organisasi yang bisa ditemukan dan dipakai ulang. Siklus harus menangkap solusi, memvalidasi dan memberi konteks, lalu menyimpan serta mengindeksnya. Memperinci profil pakar memperbaiki pencarian orang, bukan reuse isi jawaban.","options":["Validasi solusi serta konteksnya, lalu indekskan di repositori","Perinci profil pakar, lalu prioritaskan routing padanya","Salin jawaban ke FAQ tanpa syarat penerapannya","Tutup tiket lebih cepat, lalu ukur tiket yang selesai","Sebarkan daftar pakar, lalu hapus pencarian repositori"],"analysis":["Menghubungkan penyelesaian kasus dengan capture, refinement dan penemuan kembali.","Memperkuat ketergantungan kepada pakar tanpa menyediakan solusi untuk reuse.","Menyimpan isi tetapi menghilangkan validasi dan konteks untuk penerapan berbeda.","Memperbaiki metrik aktivitas tanpa membuat pengetahuan tersedia pada kasus berulang.","Mempermudah kontak tetapi menghilangkan jalur memakai pengetahuan terdokumentasi."],"answer":0,"type":"mc","pool":"exam","source":"Chapter 5: slide S5 dan buku B5; kasus baru dalam cakupan bab."},{"id":"exam-5-3","chapter":5,"topic":"Evaluasi transfer e-learning","section":"s4","prompt":"Pelatihan prosedur melalui LMS mencapai completion 98%, tetapi kesalahan penerapan pada pekerjaan belum turun. Manajemen ingin menguji apakah peserta mampu menggunakan pengetahuan pada tugas nyata. Evaluasi paling langsung adalah…","reason":"Completion mengukur penyelesaian aktivitas, bukan penguasaan prosedur. Transfer perlu diuji dengan tugas penerapan serta ukuran kesalahan yang sesuai, memakai baseline atau kelompok sebanding. Ini membantu membedakan kompetensi dari penyebab operasi lain; skor aktivitas akses saja tidak menunjukkan transfer.","options":["Kecepatan unduh konten dan uptime sistem LMS","Jumlah sertifikat dan ketepatan pencatatan nilai","Asesmen tugas representatif dan perbandingan kesalahan kerja","Tambahan jam video dan jumlah modul yang dibuka","Survei kenyamanan antarmuka dan kepuasan peserta"],"analysis":["Menguji akses teknis, bukan perpindahan pengetahuan ke pekerjaan.","Menguji administrasi penyelesaian, sementara masalahnya kompetensi penerapan.","Mengukur penerapan prosedur serta hasil yang menjadi tujuan pelatihan.","Masih mengukur paparan serta akses, bukan kemampuan menerapkan prosedur.","Mengukur pengalaman, tetapi tidak langsung menunjukkan kemampuan kerja."],"answer":2,"type":"mc","pool":"exam","source":"Chapter 5: slide S5 dan buku B5; kasus baru dalam cakupan bab."},{"id":"exam-5-4","chapter":5,"topic":"Audit e-voting","section":"s3","prompt":"Mesin voting memverifikasi pemilih dan mengumumkan total suara dengan cepat. Tanpa bukti untuk memeriksa ulang penghitungan, dua kemampuan itu sudah memenuhi kebutuhan audit hasil.","reason":"Autentikasi menjawab keabsahan pelaku, kecepatan menjawab performa, dan audit menjawab kemampuan memverifikasi hasil. Satu kemampuan tidak menggantikan yang lain. Slide Chapter 5 menekankan keamanan serta audit; kunci kuis lama yang meremehkan keamanan tidak dijadikan dasar.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Autentikasi menjawab keabsahan pelaku, kecepatan menjawab performa, dan audit menjawab kemampuan memverifikasi hasil. Satu kemampuan tidak menggantikan yang lain. Slide Chapter 5 menekankan keamanan serta audit; kunci kuis lama yang meremehkan keamanan tidak dijadikan dasar."],"answer":1,"type":"tf","pool":"exam","source":"Chapter 5: slide S5 dan buku B5; kasus baru dalam cakupan bab."},{"id":"exam-5-5","chapter":5,"topic":"E-health dan transaksi","section":"s6","prompt":"Rumah sakit mengirim hasil laboratorium ke rekam pasien dan mengatur konsultasi melalui jaringan. Ini dapat termasuk e-health walaupun tidak tersedia pembelian obat atau pembayaran online.","reason":"E-health mencakup informasi, koordinasi, administrasi dan layanan kesehatan melalui sistem elektronik. Pembelian obat adalah salah satu aplikasi, bukan syarat setiap layanan e-health. Klasifikasi mengikuti aktivitas yang dilakukan, bukan keberadaan checkout.","options":["Benar","Salah"],"analysis":["E-health mencakup informasi, koordinasi, administrasi dan layanan kesehatan melalui sistem elektronik. Pembelian obat adalah salah satu aplikasi, bukan syarat setiap layanan e-health. Klasifikasi mengikuti aktivitas yang dilakukan, bukan keberadaan checkout.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Chapter 5: slide S5 dan buku B5; kasus baru dalam cakupan bab."},{"id":"exam-5-6","chapter":5,"topic":"Knowledge refinement","section":"s5","prompt":"Komunitas teknisi memiliki solusi terdokumentasi. Anggota kemudian menguji solusi pada kondisi berbeda dan menambahkan batas penggunaan. Aktivitas lanjutan ini memberi bukti knowledge refinement meskipun berlangsung di komunitas sosial.","reason":"Refinement memperbaiki kelayakan penggunaan melalui validasi dan konteks. Penciptaan, pencatatan, serta penyempurnaan dapat terjadi pada komunitas yang sama. Nama media tidak menentukan tahap KM; pengujian serta pemberian batas menjadi bukti utama dalam kasus.","options":["Benar","Salah"],"analysis":["Refinement memperbaiki kelayakan penggunaan melalui validasi dan konteks. Penciptaan, pencatatan, serta penyempurnaan dapat terjadi pada komunitas yang sama. Nama media tidak menentukan tahap KM; pengujian serta pemberian batas menjadi bukti utama dalam kasus.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Chapter 5: slide S5 dan buku B5; kasus baru dalam cakupan bab."}];
